package kicadactions

// designActions are composite board engineering actions that close the gaps
// listed in the EDA Agent shortfall review (persistent plane layer types,
// via-in-pad and protected vias, verified planes, rule areas and antenna
// keepouts, region rules, library footprint placement and fiducials,
// decoupling, live DRC, unified checks, full DFM and length matching).  Each
// mutating action reads its result back before it reports success.
func designActions() []ActionSpec {
	doc := "document (board path; must be open in KiCad for IPC steps)"
	return []ActionSpec{
		{Name: "board.layers.type.get", Domain: DomainBoard, Backend: BackendComposite,
			Description: "Read copper layer types (signal/power/mixed/jumper) from the open board (live) or the saved file.",
			Inputs:      []string{doc}, Outputs: []string{"copperLayers", "source"},
			Keywords:    []string{"层类型", "内电层", "电源层", "plane layer", "layer type"}},
		{Name: "board.layers.type.set", Domain: DomainBoard, Backend: BackendComposite, Mutates: true,
			Description: "Set copper layer types persistently (e.g. In1.Cu/In2.Cu = power). Rewrites the board's layer table, reloads the open board and verifies the types by reading them back from KiCad. Unsaved edits require saveFirst=true.",
			Inputs:      []string{doc, "layers {\"In1.Cu\":\"power\"}", "saveFirst optional", "dryRun optional"},
			Outputs:     []string{"changed", "readback", "verified", "backup"}, VerifyWith: []string{"board.layers.type.get"},
			Keywords:    []string{"设为电源层", "设为平面层", "内电层持久化", "PLANE", "set plane layer"}},
		{Name: "board.via.create", Domain: DomainBoard, Backend: BackendComposite, Mutates: true,
			Description: "Create vias (through/blind/buried/micro) at positions or in the pads of a footprint (via-in-pad), with drill/diameter and IPC-4761 filled/capped/plugged/covered settings; every via is read back and checked.",
			Inputs:      []string{doc, "positions[] {xMm,yMm,net?} | position | reference + pads[]/nets[] (via-in-pad)", "net optional", "drillMm optional (0.3)", "diameterMm optional (0.6)", "type optional (through|blind|buried|micro)", "startLayer/endLayer optional", "filled optional", "capped optional", "plugged optional (none|front|back|both)", "covered optional (none|front|back|both)", "dryRun optional"},
			Outputs:     []string{"createdIds", "verified", "mismatches"}, VerifyWith: []string{"board.drc.live", "board.connectivity.prove"},
			Keywords:    []string{"添加过孔", "打过孔", "盘中孔", "填充过孔", "塞孔", "盖油", "via-in-pad", "filled via", "capped via", "缝合孔"}},
		{Name: "board.via.modify", Domain: DomainBoard, Backend: BackendComposite, Mutates: true,
			Description: "Batch-modify existing vias selected by ids[], nets[] or all=true: drill, diameter, type, layer span and filled/capped/plugged/covered; read back and verified.",
			Inputs:      []string{doc, "ids[] | nets[] | all", "drillMm/diameterMm/type/startLayer/endLayer/filled/capped/plugged/covered optional", "dryRun optional"},
			Outputs:     []string{"updatedIds", "verified", "mismatches"},
			Keywords:    []string{"批量修改过孔", "过孔尺寸", "modify vias"}},
		{Name: "board.plane.build", Domain: DomainBoard, Backend: BackendComposite, Mutates: true,
			Description: "Build a verified plane for ANY net: create a net-bound zone on the given layers, fill it, require real filled copper on every layer, no unconnected pads/vias and a zone-aware connectivity proof; optionally mark the inner layers as power. An unverified plane is removed (keepOnFailure=false) so no fake pour remains.",
			Inputs:      []string{doc, "net", "layers[]", "outline[] optional (default: board outline)", "clearanceMm optional", "minThicknessMm optional", "priority optional", "name optional", "layerType optional (power|mixed)", "keepOnFailure optional"},
			Outputs:     []string{"zone", "verify", "connectivity", "verified"}, VerifyWith: []string{"board.drc.live"},
			Keywords:    []string{"内电层", "电源平面", "地平面", "铺铜", "平面分割", "power plane", "ground plane", "pour"}},
		{Name: "board.rule_area.create", Domain: DomainBoard, Backend: BackendComposite, Mutates: true,
			Description: "Create a named rule area (keepout and/or region for custom rules such as T1/T2) from outline points, a box, or a footprint's bounding box/pads plus margin; read back to verify name, layers and keepout flags.",
			Inputs:      []string{doc, "name", "outline[] {xMm,yMm} | box {x1Mm,y1Mm,x2Mm,y2Mm} | reference + marginMm + pads[]", "layers[] optional (default all copper)", "keepout {tracks,vias,pads,copper,footprints} optional", "dryRun optional"},
			Outputs:     []string{"zone", "verified"}, VerifyWith: []string{"board.drc.live"},
			Keywords:    []string{"禁布区", "规则区域", "区域规则", "keepout", "rule area"}},
		{Name: "board.keepout.antenna", Domain: DomainBoard, Backend: BackendComposite, Mutates: true,
			Description: "Create an antenna keepout (no tracks, vias or copper on all copper layers) around ANY footprint reference or its antenna pads, e.g. U21 (AP6212) — not limited to a module name whitelist.",
			Inputs:      []string{doc, "reference", "pads[] optional (antenna pins)", "marginMm optional (2)", "layers[] optional", "keepoutFootprints optional"},
			Outputs:     []string{"zone", "verified"}, Keywords: []string{"天线净空", "天线禁布", "antenna keepout", "WiFi", "蓝牙"}},
		{Name: "board.rules.region.set", Domain: DomainBoard, Backend: BackendComposite, Mutates: true,
			Description: "Write named custom DRC rules scoped to a rule area (A.insideArea('T1')): clearance, track width, via diameter, hole size, annular width, hole clearance, or raw rules[]; same-name rules are replaced, then read back.",
			Inputs:      []string{doc, "area", "clearanceMm/trackWidthMm/trackWidthMaxMm/viaDiameterMm/holeSizeMm/annularWidthMm/holeClearanceMm optional", "condition optional", "rules[] optional (CustomRule proto JSON)", "dryRun optional"},
			Outputs:     []string{"added", "replaced", "verified"}, VerifyWith: []string{"board.drc.live"},
			Keywords:    []string{"区域规则", "BGA区规则", "分区规则", "间距矩阵", "region rules", "custom rules"}},
		{Name: "board.footprint.place", Domain: DomainBoard, Backend: BackendComposite, Mutates: true,
			Description: "Place a library footprint (libId 'Lib:Name' or a .kicad_mod file) at a position/angle/side: pads, outlines and fields are translated and created through the API, then read back (pad count, reference, side). Unsupported elements are listed, not dropped silently.",
			Inputs:      []string{doc, "libId | file", "reference", "position {xMm,yMm}", "angleDeg optional", "side optional (top|bottom)", "value optional", "dryRun optional"},
			Outputs:     []string{"id", "pads", "skipped", "verified"},
			Keywords:    []string{"放置封装", "添加测试点", "安装孔", "place footprint", "test point", "mounting hole"}},
		{Name: "board.fiducial.add", Domain: DomainBoard, Backend: BackendComposite, Mutates: true,
			Description: "Add global fiducials (3 asymmetric corners by default) inside the board outline, clear of existing footprints, from Fiducial:Fiducial_1mm_Mask2mm or another library footprint; read back.",
			Inputs:      []string{doc, "count optional (1..4)", "insetMm optional (3)", "clearanceMm optional (1.5)", "libId optional", "side optional", "referencePrefix optional (FID)", "force optional", "dryRun optional"},
			Outputs:     []string{"sites", "placed", "verified"},
			Keywords:    []string{"基准点", "Mark点", "光学定位点", "fiducial"}},
		{Name: "board.decap.check", Domain: DomainBoard, Backend: BackendComposite,
			Description: "Check that every IC power pin has a decoupling capacitor on the same net within maxDistanceMm (power pins by pin type or power-like net name; ground excluded).",
			Inputs:      []string{doc, "maxDistanceMm optional (3)", "ics[] optional", "nets[] optional", "icPrefixes[] optional (U, IC)"},
			Outputs:     []string{"findings", "nearest", "status"},
			Keywords:    []string{"去耦电容", "退耦", "电容太远", "decoupling", "decap"}},
		{Name: "board.decap.place", Domain: DomainBoard, Backend: BackendComposite, Mutates: true,
			Description: "Move the nearest free capacitor on each failing power net next to its pin (dry-run by default). Applied moves are read back and checked with live DRC; if violations rise, all moves are reverted.",
			Inputs:      []string{doc, "apply optional", "maxDistanceMm optional", "offsetMm optional (1)", "ics[]/nets[] optional", "skipDrc optional"},
			Outputs:     []string{"moves", "unresolved", "drcBefore", "drcAfter", "verified"},
			Keywords:    []string{"重摆电容", "电容靠近", "move decoupling capacitors"}},
		{Name: "board.drc.live", Domain: DomainBoard, Backend: BackendComposite,
			Description: "Native KiCad DRC of the OPEN board including unsaved edits (KiCad saves a temporary copy with its project rules; kicad-cli checks it). Configurable timeoutMs; the same as board.drc.run with document instead of input.",
			Inputs:      []string{doc, "timeoutMs optional", "refillZones optional", "severityAll optional", "schematicParity optional", "units optional"},
			Outputs:     []string{"status", "reportJson", "checkedCopy"},
			Keywords:    []string{"实时DRC", "未保存DRC", "DRC超时", "live drc"}},
		{Name: "schematic.erc.live", Domain: DomainSchematic, Backend: BackendComposite,
			Description: "Native ERC of the OPEN schematic including unsaved edits (via a temporary copy).",
			Inputs:      []string{"document (schematic path)", "timeoutMs optional", "severityAll optional"},
			Outputs:     []string{"status", "reportJson"}, Keywords: []string{"实时ERC", "live erc"}},
		{Name: "board.check.unified", Domain: DomainBoard, Backend: BackendComposite,
			Description: "One report from native DRC (sign-off count) plus DFM, zone-aware connectivity, decoupling distance, fiducial presence and antenna keepout checks, each finding tagged with its source so counts are never mixed; optionally adds non-DRC findings as KiCad DRC markers. Never claims fabrication readiness (use audit.run).",
			Inputs:      []string{"document (open board) | input (saved board)", "maxDecapDistanceMm optional", "minWidthMm optional", "fiducials optional (expected, 3)", "antennaRefs[] optional", "injectMarkers optional", "timeoutMs optional"},
			Outputs:     []string{"findings", "summary", "sources", "status"},
			Keywords:    []string{"全面检查", "统一检查", "板子检查", "检查PCB", "check board", "review"}},
		{Name: "board.dfm.full", Domain: DomainBoard, Backend: BackendComposite, Mutates: true,
			Description: "Full DFM pass: narrow tracks, off-45° and zero-length segments, dangling track stubs, acute junctions and wrongly mirrored silk text. fix=true widens tracks, removes stubs (restored if connectivity gets worse) and corrects silk mirroring, then re-analyzes.",
			Inputs:      []string{doc, "fix optional", "minWidthMm optional (0.15)", "acuteDeg optional (90)"},
			Outputs:     []string{"issues", "findings", "remaining"}, VerifyWith: []string{"board.drc.live"},
			Keywords:    []string{"可制造性", "DFM修复", "批量修复", "线宽", "锐角", "悬空走线", "丝印镜像", "fix all"}},
		{Name: "board.route.length_match", Domain: DomainBoard, Backend: BackendComposite, Mutates: true,
			Description: "Length-match a group of nets: measure, choose the target (targetMm or the longest), serpentine-tune the short nets and re-measure; passes only if every net is within toleranceMm. Dry-run unless apply=true.",
			Inputs:      []string{doc, "nets[]", "targetMm optional", "toleranceMm optional (0.5)", "amplitudeMm optional", "spacingMm optional", "apply optional"},
			Outputs:     []string{"nets", "after", "verified"}, VerifyWith: []string{"board.drc.live"},
			Keywords:    []string{"等长", "等长组", "长度匹配", "DDR", "length match", "bus"}},
	}
}
